import React from "react";
import "./HomePage.css";
import { useNavigate } from "react-router-dom";

export default function HomePage({ isLogin, onLogin }) {
  const navigate = useNavigate();
  const name = localStorage.getItem("name"); // ✅ NAME

  const handleStartCoding = (e) => {
    e.preventDefault();

    if (!isLogin) {
      onLogin();
    } else {
      navigate("/editor");
    }
  };

  return (
    <section id="homePage" className="homepage">
      <div className="hero">
        <div className="hero-text">

          {/* ✅ ONLY NAME */}
          {isLogin && (
            <h1 className="title">
              <span className="accent">{name}</span>
            </h1>
          )}

          <p className="subtitle">
            🚀 Daily Coding Challenges — Short tasks in Python, JavaScript, C++, Java and more.
          </p>

          <div className="cta-row">
            <a href="#" className="cta" onClick={handleStartCoding}>
              Start Coding →
            </a>
          </div>
        </div>

        <div className="hero-image">
          <img
            src="https://media.giphy.com/media/qgQUggAC3Pfv687qPC/giphy.gif"
            alt="Developer at work"
          />
        </div>
      </div>
    </section>
  );
}
